INSERT INTO public.courses (slug, content, published) VALUES
('coding-foundations', '{"title":"Coding Foundations for Young Creators","subtitle":"Think like a programmer with blocks, then Python","description":"A friendly first step into programming. Students build games and small tools while learning variables, loops, conditions and functions.","subject":"coding","difficulty":"Beginner","ageGroup":"10-12","format":"Project-based","price":49,"featured":true,"publishedAt":"2026-09-10","includedInSubscription":true,"objectives":["Understand sequences, loops and conditions","Build three small games","Write first Python programs","Debug code with confidence"],"prerequisites":["Basic reading and typing skills"],"requirements":["A computer with a modern browser","Curiosity!"],"curriculum":[{"title":"Getting started","lessons":[{"title":"Welcome & how this course works","minutes":5,"preview":true},{"title":"What is code?","minutes":9,"preview":true}]},{"title":"Block coding","lessons":[{"title":"Sequences and events","minutes":14},{"title":"Loops","minutes":16},{"title":"Project: Maze game","minutes":25}]},{"title":"Hello, Python","lessons":[{"title":"Variables and input","minutes":15},{"title":"If / else","minutes":17},{"title":"Project: Quiz app","minutes":28}]}],"faqs":[{"q":"How long do I have access?","a":"Individual purchases include lifetime access to the course unless stated otherwise."},{"q":"Do I need to attend live sessions?","a":"No. Every lesson is recorded so you can learn at your own pace."}]}'::jsonb, true),
('money-smart-teens', '{"title":"Money Smart: Personal Finance for Teens","subtitle":"Budgeting, saving and how businesses make money","description":"Practical finance taught by an accounting professional. Learn to budget, understand interest, and read a simple income statement.","subject":"finance","difficulty":"Beginner","ageGroup":"13-15","format":"Video + Quizzes","price":39,"featured":true,"publishedAt":"2026-08-22","includedInSubscription":true,"objectives":["Build a personal budget","Understand saving and compound interest","Know the difference between needs and wants","Read a simple business statement"],"prerequisites":["Basic arithmetic"],"requirements":["Notebook or spreadsheet app"],"curriculum":[{"title":"Money basics","lessons":[{"title":"Where money comes from","minutes":8,"preview":true},{"title":"Needs vs wants","minutes":11}]},{"title":"Budgeting & saving","lessons":[{"title":"Your first budget","minutes":18},{"title":"Compound interest","minutes":15},{"title":"Quiz: Saving","minutes":10}]},{"title":"Business thinking","lessons":[{"title":"Revenue, costs, profit","minutes":16},{"title":"Reading an income statement","minutes":20}]}],"faqs":[{"q":"How long do I have access?","a":"Individual purchases include lifetime access to the course unless stated otherwise."},{"q":"Do I need to attend live sessions?","a":"No. Every lesson is recorded so you can learn at your own pace."}]}'::jsonb, true),
('robotics-starter', '{"title":"Robotics Starter: Build & Program","subtitle":"Sensors, motors and your first autonomous robot","description":"Learn how robots sense and move. Program simulated and real robots to follow lines, avoid obstacles and solve challenges.","subject":"robotics","difficulty":"Intermediate","ageGroup":"13-15","format":"Project-based","price":59,"featured":true,"publishedAt":"2026-10-01","includedInSubscription":false,"objectives":["Explain how sensors and motors work","Program a line-following robot","Design obstacle-avoidance logic","Plan and test a robotics project"],"prerequisites":["Coding Foundations or equivalent"],"requirements":["Computer with browser (simulator included)","Optional: a beginner robotics kit"],"curriculum":[{"title":"How robots work","lessons":[{"title":"Sense, think, act","minutes":10,"preview":true},{"title":"Motors and wheels","minutes":14}]},{"title":"Programming robots","lessons":[{"title":"Using the simulator","minutes":12},{"title":"Line following","minutes":22},{"title":"Obstacle avoidance","minutes":24}]},{"title":"Final challenge","lessons":[{"title":"Project brief","minutes":8},{"title":"Build, test, improve","minutes":30}]}],"faqs":[{"q":"How long do I have access?","a":"Individual purchases include lifetime access to the course unless stated otherwise."},{"q":"Do I need to attend live sessions?","a":"No. Every lesson is recorded so you can learn at your own pace."}]}'::jsonb, true)
